import React,{useState} from 'react'; import './TechStack.css';
const stacks={Mobile:['Swift','SwiftUI','UIKit','Kotlin','Jetpack Compose','React Native','Flutter'],Backend:['Node.js','PHP','MySQL','Java','.NET','Python','Rails','Go','MongoDB'],Frontend:['React','Next.js','JavaScript','TypeScript','HTML5','CSS3','Redux'],Databases:['MySQL','PostgreSQL','MongoDB','Redis','Firebase'],CMS:['Shopify','WordPress','Webflow','Contentful'],Cloud:['AWS','Google Cloud','Docker','Kubernetes']};
const TechStack=()=>{const [active,setActive]=useState('Mobile');return <section className="tech-section"><span className="mini-rule"/><h2>Our<br/><b>Tech Stack</b></h2><div className="tech-tabs">{Object.keys(stacks).map(tab=><button className={active===tab?'active':''} onClick={()=>setActive(tab)} key={tab}>{tab}</button>)}</div><div className="tech-logos">{stacks[active].map((tool,index)=><span key={tool} className={`tool tool-${index}`}>{tool}</span>)}</div></section>};
export default TechStack;
